using System.Text; using System.Text.Json; using Microsoft.AspNetCore.Authentication.JwtBearer; using Microsoft.AspNetCore.Identity; using Microsoft.EntityFrameworkCore; using Microsoft.IdentityModel.Tokens; using MotoHubAPI.Data; using MotoHubAPI.Models;
var builder=WebApplication.CreateBuilder(args);
builder.Services.AddControllers();builder.Services.AddEndpointsApiExplorer();builder.Services.AddSwaggerGen();builder.Services.AddDbContext<MotoHubDbContext>(o=>o.UseSqlServer(builder.Configuration.GetConnectionString("MotoHubDb")));builder.Services.AddHttpClient();
var jwtKey=builder.Configuration["Jwt:Key"]??throw new InvalidOperationException("Configure Jwt:Key.");if(jwtKey.Length<32)throw new InvalidOperationException("Jwt:Key must contain at least 32 characters.");
builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme).AddJwtBearer(o=>{o.TokenValidationParameters=new TokenValidationParameters{ValidateIssuer=true,ValidIssuer=builder.Configuration["Jwt:Issuer"],ValidateAudience=true,ValidAudience=builder.Configuration["Jwt:Audience"],ValidateIssuerSigningKey=true,IssuerSigningKey=new SymmetricSecurityKey(Encoding.UTF8.GetBytes(jwtKey)),ValidateLifetime=true,ClockSkew=TimeSpan.FromSeconds(30)};});builder.Services.AddAuthorization();builder.Services.AddCors(o=>o.AddPolicy("Frontend",p=>p.WithOrigins("http://127.0.0.1:5500","http://localhost:5500","http://127.0.0.1:5501","http://localhost:5501").AllowAnyHeader().AllowAnyMethod()));
var app=builder.Build();app.UseExceptionHandler(error=>error.Run(async context=>{context.Response.StatusCode=500;context.Response.ContentType="application/json";await context.Response.WriteAsync(JsonSerializer.Serialize(new{message="Unexpected server error. Check server logs."}));}));if(app.Environment.IsDevelopment()){app.UseSwagger();app.UseSwaggerUI();}app.UseCors("Frontend");app.UseAuthentication();app.UseAuthorization();app.MapControllers();app.MapGet("/",()=>Results.Ok(new{app="MotoHub API",status="running",docs="/swagger"}));
// Create the database and a demo admin account for local development. Change the demo password before any real deployment.
using(var scope=app.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<MotoHubDbContext>();await db.Database.EnsureCreatedAsync();if(!await db.Users.AnyAsync(u=>u.Email=="admin@motohub.local")){var admin=new AppUser{FullName="MotoHub Administrator",Email="admin@motohub.local",Role="Admin"};admin.PasswordHash=new PasswordHasher<AppUser>().HashPassword(admin,Environment.GetEnvironmentVariable("MOTOHUB_ADMIN_PASSWORD")??"ChangeMe123!");db.Users.Add(admin);if(!await db.Services.AnyAsync()){db.Services.AddRange(new ServiceItem{Name="Basic Maintenance",Description="General inspection and basic maintenance",Price=500,DurationMinutes=60},new ServiceItem{Name="Oil Change",Description="Engine oil replacement",Price=350,DurationMinutes=30},new ServiceItem{Name="Brake Service",Description="Brake inspection and adjustment",Price=650,DurationMinutes=60});}if(!await db.Parts.AnyAsync()){db.Parts.AddRange(new PartItem{Name="Engine Oil",SKU="OIL-001",Price=250,Stock=20},new PartItem{Name="Brake Pad Set",SKU="BRK-001",Price=450,Stock=10});}await db.SaveChangesAsync();}}
app.Run();
